use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclfn! {
fn analyze_ngrams_for_size (source_dir : & Path , n : usize , top_k : usize) -> Result < RustcOntology > { let mut analyzer = NGramAnalyzer :: new () ; let mut file_count = 0 ; println ! ("🔍 Analyzing {}-grams in {:?}..." , n , source_dir) ; for entry in walkdir :: WalkDir :: new (source_dir) { let entry = entry ? ; if entry . file_type () . is_file () { if let Err (e) = analyzer . analyze_file (entry . path () , n) { eprintln ! ("Warning: Failed to analyze {:?}: {}" , entry . path () , e) ; } else { file_count += 1 ; if file_count % 100 == 0 { println ! ("  Processed {} files..." , file_count) ; } } } } let total_patterns = analyzer . patterns . len () ; let top_patterns = analyzer . get_top_patterns (top_k) ; let coverage = if total_patterns > 0 { (top_patterns . iter () . map (| p | p . frequency) . sum :: < usize > () as f64 / analyzer . patterns . values () . map (| (f , _) | f) . sum :: < usize > () as f64) * 100.0 } else { 0.0 } ; println ! ("✅ Found {} unique {}-grams from {} files" , total_patterns , n , file_count) ; Ok (RustcOntology { ngram_size : n , top_patterns , total_patterns , coverage_percentage : coverage , }) }
}